 1	import { readFileSync } from "node:fs";
 2	import { join } from "node:path";
 3	import { PrismaClient } from "@prisma/client";
 4	
 5	const prisma = new PrismaClient();
 6	const MIGRATIONS_DIR = join(process.cwd(), "prisma", "migrations");
 7	
 8	export type Migration = {
 9	  id: string;
10	  file: string;
11	};
12	
13	/** Hand-written SQL migrations, applied in array order. */
14	export const MIGRATIONS: Migration[] = [
15	  { id: "20240226141200_add_task_priority", file: "migration.sql" },
16	  { id: "20240412100500_add_task_indexes", file: "migration.sql" },
17	];
18	
19	export function loadSql(m: Migration): string {
20	  return readFileSync(join(MIGRATIONS_DIR, m.id, m.file), "utf8");
21	}
22	
23	export function statements(sql: string): string[] {
24	  return sql
25	    .split(/;\s*$/m)
26	    .map((s) => s.trim())
27	    .filter((s) => s.length > 0 && !s.startsWith("--"));
28	}
29	
30	export async function run(): Promise<void> {
31	  for (const m of MIGRATIONS) {
32	    console.log(`[migrate] applying ${m.id}`);
33	    for (const stmt of statements(loadSql(m))) {
34	      await prisma.$executeRawUnsafe(stmt);
35	    }
36	  }
37	  console.log(`[migrate] done (${MIGRATIONS.length} migrations)`);
38	}
39	
40	if (process.argv[1]?.endsWith("backfill.ts")) {
41	  run()
42	    .then(() => prisma.$disconnect())
43	    .catch(async (err) => {
44	      console.error("[migrate] failed", err);
45	      await prisma.$disconnect();
46	      process.exit(1);
47	    });
48	}

