-- 20240705101500_backfill_tasks_updated_at
-- Adds tasks.updated_at, seeds it from created_at, then enforces default + NOT NULL.
-- Re-runnable: the UPDATE only touches rows that are still NULL.

ALTER TABLE "tasks"
  ADD COLUMN "updated_at" TIMESTAMPTZ;

UPDATE "tasks"
SET "updated_at" = COALESCE("created_at", now())
WHERE "updated_at" IS NULL;

ALTER TABLE "tasks"
  ALTER COLUMN "updated_at" SET DEFAULT now();

ALTER TABLE "tasks"
  ALTER COLUMN "updated_at" SET NOT NULL;

CREATE INDEX IF NOT EXISTS "tasks_updated_at_idx" ON "tasks" ("updated_at");
